package dev.untangle.common.audit;

import jakarta.persistence.Column;
import jakarta.persistence.Id;
import jakarta.persistence.MappedSuperclass;
import java.util.Objects;
import java.util.UUID;
import lombok.Getter;
import org.hibernate.annotations.UuidGenerator;
import org.hibernate.proxy.HibernateProxy;

/**
 * Root of every entity: a time-ordered UUIDv7 primary key and identity-based equality.
 *
 * <p>Why UUIDv7 (ADR-008): ids can be generated by the application before insert, are safe to
 * expose in URLs (not guessable sequences), and, unlike random v4 ids, are ordered by creation
 * time, so B-tree index inserts stay sequential.
 *
 * <p>Why this equals/hashCode: JPA entities are compared by database identity. A new entity has no
 * id until it is persisted, so two unsaved instances are never equal. {@code hashCode} is constant
 * per class so an entity keeps the same hash before and after it gets an id (otherwise it would get
 * "lost" inside a HashSet). Lombok's {@code @Data}/{@code @EqualsAndHashCode} must never be used on
 * entities because they break exactly these rules.
 */
@Getter
@MappedSuperclass
public abstract class BaseEntity {

  @Id
  @UuidGenerator(style = UuidGenerator.Style.VERSION_7)
  @Column(name = "id", nullable = false, updatable = false)
  private UUID id;

  @Override
  public final boolean equals(Object other) {
    if (this == other) {
      return true;
    }
    if (other == null || effectiveClass(this) != effectiveClass(other)) {
      return false;
    }
    UUID otherId = ((BaseEntity) other).getId();
    return id != null && Objects.equals(id, otherId);
  }

  @Override
  public final int hashCode() {
    return effectiveClass(this).hashCode();
  }

  /** Unwraps Hibernate lazy-loading proxies so a proxy and its target compare as equal. */
  private static Class<?> effectiveClass(Object entity) {
    return entity instanceof HibernateProxy proxy
        ? proxy.getHibernateLazyInitializer().getPersistentClass()
        : entity.getClass();
  }

  @Override
  public String toString() {
    return getClass().getSimpleName() + "[id=" + id + "]";
  }
}
